local keywordHandler = KeywordHandler:new()
local npcHandler = NpcHandler:new(keywordHandler)
NpcSystem.parseParameters(npcHandler)

function onCreatureAppear(cid)			npcHandler:onCreatureAppear(cid)			end
function onCreatureDisappear(cid)		npcHandler:onCreatureDisappear(cid)			end
function onCreatureSay(cid, type, msg)	npcHandler:onCreatureSay(cid, type, msg)	end
function onThink()						npcHandler:onThink()						end
npcHandler:setMessage(MESSAGE_FAREWELL, 'Aww - you really have to leave so soon? You must come and visit me again. Please - promise me!')
npcHandler:setMessage(MESSAGE_WALKAWAY, 'Aww - you really have to leave so soon? You must come and visit me again. Please - promise me!')
keywordHandler:addKeyword({'alesar'}, StdModule.say, {npcHandler = npcHandler, text = 'I have never known this djinn, but apparently there is some sad story behind this. Daddy is very sad that Alesar left us. Of course, he tries not to show, but as usual he does a bad job about it.'})
keywordHandler:addKeyword({'ascension'}, StdModule.say, {npcHandler = npcHandler, text = 'I have heard that term before. Has to do with the pharaoh\'s cult, I think, but I do not know for sure, and I\'m not particularly eager to learn more about it.'})
keywordHandler:addKeyword({'melchior'}, StdModule.say, {npcHandler = npcHandler, text = 'Hm. I think I have heard that name before. A human, wasn\'t it? I think he used to drop quite often when I was much younger, but I have no clear memory of him. ...'})
keywordHandler:addKeyword({'librarian'}, StdModule.say, {npcHandler = npcHandler, text = 'Yes. I administrate the library. You know - registering new books, sorting them in alphabetical order etc. ...'})
keywordHandler:addKeyword({'djinn'}, StdModule.say, {npcHandler = npcHandler, text = 'The djinn are a curious race. They are nice, but they are always so serious. Oh, don\'t get me wrong, there is not a single djinn around here I do not like, but, you know, they are not much fun. ...'})
keywordHandler:addKeyword({'darashia'}, StdModule.say, {npcHandler = npcHandler, text = 'Darashia is a beautiful city to the north. I have been there! One day Daddy disguised himself, and he took me there. It was awesome. ...'})
keywordHandler:addKeyword({'job'}, StdModule.say, {npcHandler = npcHandler, text = 'I am the librarian in this place. I don\'t like the work too much because we do not really have that many books, and most of them are written by people who have died thousands of years ago. ...'})
keywordHandler:addKeyword({'daraman'}, StdModule.say, {npcHandler = npcHandler, text = 'Daraman was a human, but he must have been something very special - he was a holy man. To this day daddy and all the other djinn around here look up to Daraman as a true prophet.'})
keywordHandler:addKeyword({'ankrahmun'}, StdModule.say, {npcHandler = npcHandler, text = 'If there is one city I don\'t want to see it is Ankrahmun. I have heard all kinds of stories about the pharaoh and his cult of weirdos!'})
keywordHandler:addKeyword({'palace'}, StdModule.say, {npcHandler = npcHandler, text = 'I do not care just how beautiful the pharaoh\'s palace is. I will never go there. The minute I would see some undead pile of flesh I would dash for the door screaming.'})
keywordHandler:addKeyword({'efreet'}, StdModule.say, {npcHandler = npcHandler, text = 'Apparently the greenskins are different from the Marid who have raised me. I don\'t know. Perhaps the Efreet would be more fun than the djinn around here, but then daddy says they are really evil.'})
keywordHandler:addKeyword({'king'}, StdModule.say, {npcHandler = npcHandler, text = 'Officially there is no king of the djinn. Daddy used to hold the title, but he has chosen to put if off. Of course, he is still the undisputed leader of the Marid. He simply dislikes the title.'})
keywordHandler:addKeyword({'marid'}, StdModule.say, {npcHandler = npcHandler, text = 'The djinn you have met call themselves the Marid. They are generally very nice. Nice, but boring.'})
keywordHandler:addKeyword({'pharaoh'}, StdModule.say, {npcHandler = npcHandler, text = 'Apparently he is an undead! Yuk - how disgusting!'})
keywordHandler:addKeyword({'edron'}, StdModule.say, {npcHandler = npcHandler, text = 'I have read all about the northern cities. It is almost as if I had been there myself.'})
keywordHandler:addKeyword({'tibia'}, StdModule.say, {npcHandler = npcHandler, text = 'Daddy has often told me about how huge and mysterious this world is. <Sighs> How much I would like to see it all. But he won\'t let me go. ...'})
keywordHandler:addKeyword({'scarab'}, StdModule.say, {npcHandler = npcHandler, text = 'Ah, those nasty critters. They give me the creeps!'})
keywordHandler:addKeyword({'parents'}, StdModule.say, {npcHandler = npcHandler, text = 'I can\'t remember them. I... They have both died a long time. At least that is what I have been told. Listen, can we talk about something else?'})
keywordHandler:addKeyword({'war'}, StdModule.say, {npcHandler = npcHandler, text = 'Daddy and all the other djinn around here are so restive lately. I know they try not to show it, but I can sense that they are tense and perhaps even a bit afraid. ...'})
keywordHandler:addKeyword({'human'}, StdModule.say, {npcHandler = npcHandler, text = 'I have lived here for as long as I can remember, but I know I don\'t belong here. I belong to them! I am a human! One day I will leave this place, and I will never come back.'})
keywordHandler:addKeyword({'gabel'}, StdModule.say, {npcHandler = npcHandler, text = 'Gabel is my father. He runs this place. Of course, he is not my real daddy. But he adopted me, you know. Or rather, all the Marid adopted me.'})
keywordHandler:addKeyword({'book'}, StdModule.say, {npcHandler = npcHandler, text = 'The books around here are not exactly what I would call a riveting read. Most of them are technical documents written by uncle Fad at some point or other. Now and then he turns up and brings new files. Not that anybody would ever read them. ...'})
keywordHandler:addKeyword({'zathroth'}, StdModule.say, {npcHandler = npcHandler, text = 'Yes, I have heard his name before. Let\'s see... Yes, I have read his name in a book! It was a book about gods and creation. Pretty weird stuff.'})
keywordHandler:addKeyword({'malor'}, StdModule.say, {npcHandler = npcHandler, text = 'Malor is the leader of the Efreet. I have never seen him, but they say he is really nasty. Daddy always gets upset when this name is pronounced.'})
keywordHandler:addKeyword({'djem'}, StdModule.say, {npcHandler = npcHandler, text = 'That is my name. I do not like it much, though. Everybody around here calls me Djem.'})
keywordHandler:addKeyword({'name'}, StdModule.say, {npcHandler = npcHandler, text = 'My name is Djema. Daddy says it means \'Moonflower\' in the old language.'})
keywordHandler:addKeyword({'lamp'}, StdModule.say, {npcHandler = npcHandler, text = 'When I was still a kid I could not understand how it could be that I was not able to sleep in a lamp. ...'})

local shopModule = ShopModule:new()
npcHandler:addModule(shopModule)

local focusModule = FocusModule:new()
focusModule:addGreetMessage('hi')
focusModule:addGreetMessage('hello')
npcHandler:addModule(focusModule)

